            X=np.column_stack([t**2,np.ones_like(t),v,v*np.sin(w*t),v*np.cos(w*t)])
            c=np.linalg.lstsq(X,dv_dt,rcond=None)[0]
            return dv_dt-X@c
        def g(p): return f(p)
        s=least_squares(lambda p: g(p),[w0])
